<section class="panel"><h2 id="form-title">Ajouter un partenaire</h2><p class="hint">Le nom et le logo sont obligatoires. Le lien du site est facultatif.</p><form id="form" enctype="multipart/form-data"><input type="hidden" name="id" id="id" value="0"><div class="formgrid"><label class="field">Nom du partenaire<input name="name" id="name" maxlength="120" required placeholder="Nom du partenaire"></label><label class="field">Site web (facultatif)<input name="website_url" id="url" type="url" maxlength="500" placeholder="https://exemple.mg"></label><label class="field">Logo (PNG, JPG, WebP ou SVG)<input name="logo" id="logo" type="file" accept=".png,.jpg,.jpeg,.webp,image/png,image/jpeg,image/webp"><span class="hint" id="logo-hint">5 Mo maximum. Obligatoire pour un nouveau partenaire.</span></label><label class="field">Texte alternatif<input name="alt_text" id="alt" maxlength="180" placeholder="Logo du partenaire"></label><label class="field">Ordre d’affichage<input name="sort_order" id="order" type="number" min="0" max="10000" value="0"></label><label class="check"><input name="is_published" id="published" type="checkbox" checked> Publier dans le pied de page</label></div><div class="actions"><button class="btn" id="save" type="submit">Enregistrer le partenaire</button><button class="btn secondary" id="cancel" type="button" hidden>Annuler</button><span class="status" id="status" role="status"></span></div></form></section>
<section class="panel"><h2>Partenaires enregistrés</h2><p class="hint">Les partenaires publiés seront visibles sur le site public.</p><div class="tablewrap"><table><thead><tr><th>Logo</th><th>Nom</th><th>Lien</th><th>Ordre</th><th>Statut</th><th>Actions</th></tr></thead><tbody id="rows"><tr><td colspan="6" class="empty">Chargement…</td></tr></tbody></table></div></section></div></main></div>
<script>
const API='../api/admin/footer-partners.php';const CSRF=<?= json_encode($csrf) ?>;const form=document.querySelector('#form'),rows=document.querySelector('#rows'),status=document.querySelector('#status');let items=[];
async function req(url,opt={}){const r=await fetch(url,{credentials:'same-origin',...opt});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d?.error?.message||'Erreur serveur');return d}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function load(){try{items=(await req(API)).data||[];rows.innerHTML=items.length?items.map(p=>'<tr><td><img class="logo" src="'+esc(p.logo_url)+'" alt="'+esc(p.alt_text||p.name)+'"></td><td><strong>'+esc(p.name)+'</strong></td><td>'+(p.website_url?'<a href="'+esc(p.website_url)+'" target="_blank" rel="noopener">Ouvrir ↗</a>':'—')+'</td><td>'+p.sort_order+'</td><td><span class="tag '+(p.is_published?'':'off')+'">'+(p.is_published?'Publié':'Masqué')+'</span></td><td><div class="actions" style="margin:0"><button class="btn secondary" data-edit="'+p.id+'">Modifier</button><button class="btn danger" data-del="'+p.id+'">Supprimer</button></div></td></tr>').join(''):'<tr><td colspan="6" class="empty">Aucun partenaire enregistré.</td></tr>'}catch(e){rows.innerHTML='<tr><td colspan="6" class="empty">'+esc(e.message)+'</td></tr>'}}
function reset(){form.reset();document.querySelector('#id').value='0';document.querySelector('#order').value='0';document.querySelector('#published').checked=true;document.querySelector('#logo').required=true;document.querySelector('#logo-hint').textContent='5 Mo maximum. Obligatoire pour un nouveau partenaire.';document.querySelector('#form-title').textContent='Ajouter un partenaire';document.querySelector('#save').textContent='Enregistrer le partenaire';document.querySelector('#cancel').hidden=true;status.textContent=''}
rows.addEventListener('click',async e=>{const ed=e.target.closest('[data-edit]'),del=e.target.closest('[data-del]');if(ed){const p=items.find(x=>x.id===+ed.dataset.edit);if(!p)return;document.querySelector('#id').value=p.id;document.querySelector('#name').value=p.name;document.querySelector('#url').value=p.website_url||'';document.querySelector('#alt').value=p.alt_text||'';document.querySelector('#order').value=p.sort_order;document.querySelector('#published').checked=p.is_published;document.querySelector('#logo').required=false;document.querySelector('#logo-hint').textContent='Laisser vide pour conserver le logo actuel.';document.querySelector('#form-title').textContent='Modifier '+p.name;document.querySelector('#save').textContent='Enregistrer les modifications';document.querySelector('#cancel').hidden=false;form.scrollIntoView({behavior:'smooth'});return}if(del){const p=items.find(x=>x.id===+del.dataset.del);if(!p||!confirm('Supprimer « '+p.name+' » ?'))return;const fd=new FormData();fd.set('action','delete');fd.set('id',p.id);try{await req(API,{method:'POST',headers:{'X-CSRF-Token':CSRF},body:fd});await load()}catch(err){alert(err.message)}}});
form.addEventListener('submit',async e=>{e.preventDefault();status.className='status';status.textContent='Enregistrement…';const fd=new FormData(form);fd.set('is_published',document.querySelector('#published').checked?'1':'0');try{await req(API,{method:'POST',headers:{'X-CSRF-Token':CSRF},body:fd});status.className='status ok';status.textContent='Partenaire enregistré.';reset();await load()}catch(err){status.className='status error';status.textContent=err.message}});
document.querySelector('#cancel').addEventListener('click',reset);document.querySelector('#logo').required=true;load();
</script></body></html>